using System;
using System.Drawing;

// Store the last unrounded reference. Small successive scale changes must not
// lose font/offset growth through repeated integer rounding. Manual edits
// establish a fresh reference the next time the scale is changed.
internal sealed class ProgressScaleReference {
    public int Percent=100,Width,Height,TextSize,CurrentY,MaximumY,PercentageY,NameSize,NameX,NameY,NameLayout,CountdownSize,CountdownY;
    public int[] DetailMetrics,OutlineWidths;internal ProgressScaleReference Copy(){var c=(ProgressScaleReference)MemberwiseClone();c.DetailMetrics=DetailMetrics==null?null:(int[])DetailMetrics.Clone();c.OutlineWidths=OutlineWidths==null?null:(int[])OutlineWidths.Clone();return c;}
    static bool DetailsSame(int[] a,int[] b){if(a==null||b==null)return a==b;if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
    internal static bool Same(ProgressScaleReference a,ProgressScaleReference b){return a==null||b==null?a==b:DetailsSame(a.DetailMetrics,b.DetailMetrics)&&DetailsSame(a.OutlineWidths,b.OutlineWidths)&&a.Percent==b.Percent&&a.Width==b.Width&&a.Height==b.Height&&a.TextSize==b.TextSize&&a.CurrentY==b.CurrentY&&a.MaximumY==b.MaximumY&&a.PercentageY==b.PercentageY&&a.NameSize==b.NameSize&&a.NameX==b.NameX&&a.NameY==b.NameY&&a.NameLayout==b.NameLayout&&a.CountdownSize==b.CountdownSize&&a.CountdownY==b.CountdownY;}
}
internal static class ProgressWidgetScale {
    internal static EnergyBarOptions Bar(EnergyConfiguration c,int kind){return kind==0?c.Options:kind==1?c.Stagger.Bar:kind==2?c.EnemyHealth.Bar:c.EnemyTarget.Bar;}
    static Rectangle Bounds(EnergyConfiguration c,int kind){return kind==0?c.Bounds:kind==1?c.Stagger.Bounds:kind==2?c.EnemyHealth.Bounds:c.EnemyTarget.Bounds;}
    static ProgressScaleReference Read(EnergyConfiguration c,int kind){var b=Bar(c,kind);var r=Bounds(c,kind);var result=new ProgressScaleReference{Percent=b.ScalePercent,Width=r.Width,Height=r.Height,TextSize=b.TextSize,CurrentY=b.CurrentOffsetY,MaximumY=b.MaximumOffsetY,PercentageY=b.PercentageOffsetY};if(kind==1){result.CountdownSize=c.Stagger.Countdown.FontSize;result.CountdownY=c.Stagger.Countdown.OffsetY;}if(kind>=2){var n=(kind==2?c.EnemyHealth:c.EnemyTarget).Name;result.NameSize=n.FontSize;result.NameX=n.OffsetX;result.NameY=n.OffsetY;result.NameLayout=n.LayoutScalePercent;var d=(kind==2?c.EnemyHealth:c.EnemyTarget).Details;result.DetailMetrics=new[]{d.DistanceText.FontSize,d.DistanceText.OffsetX,d.DistanceText.OffsetY,d.DistanceText.LayoutScalePercent,d.SpeciesText.FontSize,d.SpeciesText.OffsetX,d.SpeciesText.OffsetY,d.SpeciesText.LayoutScalePercent,(kind==2?c.EnemyHealth:c.EnemyTarget).LockText.FontSize,(kind==2?c.EnemyHealth:c.EnemyTarget).LockText.OffsetX,(kind==2?c.EnemyHealth:c.EnemyTarget).LockText.OffsetY,(kind==2?c.EnemyHealth:c.EnemyTarget).LockText.LayoutScalePercent};result.OutlineWidths=new[]{b.TextOutline.Width,n.Outline.Width,d.DistanceText.Outline.Width,d.SpeciesText.Outline.Width,(kind==2?c.EnemyHealth:c.EnemyTarget).LockText.Outline.Width};}return result;}
    static int Scale(int value,double factor,int min,int max){return Math.Max(min,Math.Min(max,(int)Math.Round(Math.Max(int.MinValue,Math.Min(int.MaxValue,value*factor)))));}
    static ProgressScaleReference Scaled(ProgressScaleReference basis,int kind,int percent){double f=(double)percent/basis.Percent;return new ProgressScaleReference{Percent=percent,Width=Scale(basis.Width,f,kind>=2?80:40,kind>=2?2400:32767),Height=Scale(basis.Height,f,3,kind>=2?80:300),TextSize=Scale(basis.TextSize,f,10,144),CurrentY=Scale(basis.CurrentY,f,-600,600),MaximumY=Scale(basis.MaximumY,f,-600,600),PercentageY=Scale(basis.PercentageY,f,-600,600),NameSize=kind>=2?Scale(basis.NameSize,f,10,192):0,NameX=kind>=2?Scale(basis.NameX,f,-1500,1500):0,NameY=kind>=2?Scale(basis.NameY,f,-1500,1500):0,NameLayout=kind>=2?Scale(basis.NameLayout,f,25,900):0,CountdownSize=kind==1?Scale(basis.CountdownSize,f,10,192):0,DetailMetrics=kind>=2&&basis.DetailMetrics!=null&&basis.DetailMetrics.Length==12?ScaleDetails(basis.DetailMetrics,f):null,OutlineWidths=kind>=2&&basis.OutlineWidths!=null&&basis.OutlineWidths.Length==5?ScaleOutlines(basis.OutlineWidths,f):null,CountdownY=kind==1?Scale(basis.CountdownY,f,-600,600):0};}
    static int[] ScaleDetails(int[] data,double f){var result=new int[data.Length];for(int i=0;i<data.Length;i++){int field=i%4;result[i]=Scale(data[i],f,field==0?10:field==3?25:-1500,field==0?192:field==3?900:1500);}return result;}
    static int[] ScaleOutlines(int[] data,double f){var result=new int[data.Length];for(int i=0;i<data.Length;i++)result[i]=Scale(data[i],f,1,8);return result;}
    internal static void Apply(EnergyConfiguration c,int kind,int percent){var b=Bar(c,kind);percent=Math.Max(50,Math.Min(300,percent));if(percent==b.ScalePercent)return;var actual=Read(c,kind);var basis=b.ScaleReference;bool valid=basis!=null&&basis.Percent>=50&&basis.Percent<=300&&basis.Width>0&&basis.Height>0&&(kind<2||basis.DetailMetrics!=null&&basis.DetailMetrics.Length==12&&basis.OutlineWidths!=null&&basis.OutlineWidths.Length==5);if(!valid||!ProgressScaleReference.Same(actual,Scaled(basis,kind,b.ScalePercent)))basis=actual;var next=Scaled(basis,kind,percent);var r=Bounds(c,kind);r.Size=new Size(next.Width,next.Height);if(kind==0)c.Bounds=r;else if(kind==1)c.Stagger.Bounds=r;else (kind==2?c.EnemyHealth:c.EnemyTarget).Bounds=r;b.TextSize=next.TextSize;b.CurrentOffsetY=next.CurrentY;b.MaximumOffsetY=next.MaximumY;b.PercentageOffsetY=next.PercentageY;b.ScalePercent=percent;b.ScaleReference=basis.Copy();if(kind==1){c.Stagger.Countdown.FontSize=next.CountdownSize;c.Stagger.Countdown.OffsetY=next.CountdownY;}if(kind>=2){var n=(kind==2?c.EnemyHealth:c.EnemyTarget).Name;n.FontSize=next.NameSize;n.OffsetX=next.NameX;n.OffsetY=next.NameY;n.LayoutScalePercent=next.NameLayout;var d=(kind==2?c.EnemyHealth:c.EnemyTarget).Details;d.DistanceText.FontSize=next.DetailMetrics[0];d.DistanceText.OffsetX=next.DetailMetrics[1];d.DistanceText.OffsetY=next.DetailMetrics[2];d.DistanceText.LayoutScalePercent=next.DetailMetrics[3];d.SpeciesText.FontSize=next.DetailMetrics[4];d.SpeciesText.OffsetX=next.DetailMetrics[5];d.SpeciesText.OffsetY=next.DetailMetrics[6];d.SpeciesText.LayoutScalePercent=next.DetailMetrics[7];var lockText=(kind==2?c.EnemyHealth:c.EnemyTarget).LockText;lockText.FontSize=next.DetailMetrics[8];lockText.OffsetX=next.DetailMetrics[9];lockText.OffsetY=next.DetailMetrics[10];lockText.LayoutScalePercent=next.DetailMetrics[11];b.TextOutline.Width=next.OutlineWidths[0];n.Outline.Width=next.OutlineWidths[1];d.DistanceText.Outline.Width=next.OutlineWidths[2];d.SpeciesText.Outline.Width=next.OutlineWidths[3];lockText.Outline.Width=next.OutlineWidths[4];}}
}
